package Java_core;
import java.util.*;
public class switch_case {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner sc=new Scanner(System.in);
		int letter=65;
		switch(letter) {
		case 'A':
			System.out.println("upper");
			break;
		case 'a':
			System.out.println("upper");
			break;
		default:
			System.out.println("default");
		}

	}

}
